test("discoverWorkflows finds deep-research in builtin/", () => {
	// cwd doesn't matter for builtin discovery; pass a tmp dir with no .pi/workflows
	const all = discoverWorkflows("/tmp");
	const dr = all.find((w) => w.name === "deep-research");
	assert.ok(dr, "deep-research not discovered");
