--- src/discovery.ts
/**
 * Workflow discovery — finds named workflow scripts across three roots:
 *
 *   1. Built-in:  src/builtin/*.js (bundled with the extension)
 *   2. User:      ~/.pi/agent/workflows/*.js
 *   3. Project:   <cwd>/.pi/workflows/*.js
 *
 * Each file must declare its metadata in a pure-literal `export const meta = {...}`
 * at the top — same constraint as Claude Code's Workflow tool. We extract that
 * literal with a brace-balanced parser + JSON5-ish normalization; no execution.
 * Bodies are loaded lazily when the workflow is actually invoked.
 *
 * Name conflict policy (matches Claude Code): project > user > built-in.
 */

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import ts from "typescript";
import type { WorkflowMeta } from "./types.ts";

export type WorkflowSource = "builtin" | "user" | "project";

export interface DiscoveredWorkflow {
	name: string;
	source: WorkflowSource;
	path: string;
	meta: WorkflowMeta;
}

const BUILTIN_DIR = path.resolve(fileURLToPath(import.meta.url), "..", "builtin");
const USER_DIR = path.join(os.homedir(), ".pi", "agent", "workflows");

export function discoverWorkflows(cwd: string): DiscoveredWorkflow[] {
	const projectDir = path.join(cwd, ".pi", "workflows");

	// Lowest priority first; higher-priority entries overwrite by name.
	const all = new Map<string, DiscoveredWorkflow>();
	for (const wf of listDir(BUILTIN_DIR, "builtin")) all.set(wf.name, wf);
	for (const wf of listDir(USER_DIR, "user")) all.set(wf.name, wf);
	for (const wf of listDir(projectDir, "project")) all.set(wf.name, wf);

	return [...all.values()].sort((a, b) => a.name.localeCompare(b.name));
}

export function findWorkflowByName(cwd: string, name: string): DiscoveredWorkflow | null {
	return discoverWorkflows(cwd).find((w) => w.name === name) ?? null;
}

export function loadWorkflowSource(scriptPath: string): string {
	const stat = fs.statSync(scriptPath);
	if (stat.size > 50_000) {
		throw new Error(`Workflow file too large (${stat.size} bytes; max 50000): ${scriptPath}`);
	}
	return fs.readFileSync(scriptPath, "utf-8");
}

// ──────────────────────────────────────────────────────────────────────────────

function listDir(dir: string, source: WorkflowSource): DiscoveredWorkflow[] {
	if (!fs.existsSync(dir)) return [];

	const out: DiscoveredWorkflow[] = [];
	let entries: fs.Dirent[];
	try {
		entries = fs.readdirSync(dir, { withFileTypes: true });
	} catch {
		return [];
	}

	for (const entry of entries) {
		if (!entry.isFile() && !entry.isSymbolicLink()) continue;
		if (!entry.name.endsWith(".js") && !entry.name.endsWith(".mjs")) continue;

		const fullPath = path.join(dir, entry.name);
		try {
			const source_ = fs.readFileSync(fullPath, "utf-8");
			const meta = parseMetaLiteral(source_);
			if (!meta) continue; // No usable meta header → skip.
			out.push({
				name: meta.name,
				source,
				path: fullPath,
				meta,
			});
		} catch {
			// Bad file → skip silently. Discovery should never throw.
		}
	}
	return out;
}

/**
 * Parse `export const meta = { ... };` at module top level into a `WorkflowMeta`
 * object. The literal must be AST-pure: objects/arrays/strings/numbers/booleans/null
 * only; no spreads, computed keys, methods/accessors, template expressions, function
 * calls, or identifier references.
 *
 * Returns `null` if the meta block is missing or malformed. Discovery uses that
 * to skip files quietly rather than crashing.
 */
export function parseMetaLiteral(source: string): WorkflowMeta | null {
	const result = validateMetaLiteral(source);
	return result.meta ?? null;
}

export function validateMetaLiteral(source: string): { meta: WorkflowMeta | null; errors: string[] } {
	let file: ts.SourceFile;
	try {
		file = ts.createSourceFile("workflow-meta.js", source, ts.ScriptTarget.Latest, true, ts.ScriptKind.JS);
	} catch (e) {
		return { meta: null, errors: [`Failed to parse workflow script: ${(e as Error).message}`] };
	}
	const errors: string[] = [];
	const metaDecl = findMetaDeclaration(file);
	if (!metaDecl) {
		return { meta: null, errors: ["Script must begin with `export const meta = { name, description, phases }` (pure literal)."] };
	}
	const withoutLeading = source.replace(/^(?:\s|\/\/[^\n]*\n|\/\*[\s\S]*?\*\/)+/, "");
	if (!/^export\s+const\s+meta\b/.test(withoutLeading)) {
		return { meta: null, errors: ["`export const meta = { ... }` must be the first statement after comments/whitespace."] };
	}
	const initializer = metaDecl.initializer;
	if (!initializer || !ts.isObjectLiteralExpression(initializer)) {
		return { meta: null, errors: ["`export const meta` must be assigned a pure object literal."] };
	}
	const value = literalToValue(initializer, "meta", errors);
	if (errors.length > 0 || !isRecord(value)) return { meta: null, errors };
	const metaErrors = validateMetaShape(value);
	if (metaErrors.length > 0) return { meta: null, errors: metaErrors };
	return { meta: value as unknown as WorkflowMeta, errors: [] };
}

function findMetaDeclaration(file: ts.SourceFile): ts.VariableDeclaration | null {
	for (const stmt of file.statements) {
		if (!ts.isVariableStatement(stmt)) continue;
		const hasExport = stmt.modifiers?.some((m) => m.kind === ts.SyntaxKind.ExportKeyword) ?? false;
		if (!hasExport) continue;
		for (const decl of stmt.declarationList.declarations) {
			if (ts.isIdentifier(decl.name) && decl.name.text === "meta" && decl.initializer) return decl;
		}
	}
	return null;
}

function literalToValue(node: ts.Expression, path: string, errors: string[]): unknown {
	if (ts.isParenthesizedExpression(node)) return literalToValue(node.expression, path, errors);
	if (ts.isObjectLiteralExpression(node)) {
		const out: Record<string, unknown> = {};
		for (const prop of node.properties) {
			if (ts.isSpreadAssignment(prop)) {
				errors.push(`${path}: spreads are not allowed in workflow meta.`);
				continue;
			}
			if (ts.isMethodDeclaration(prop) || ts.isGetAccessorDeclaration(prop) || ts.isSetAccessorDeclaration(prop)) {
				errors.push(`${path}: methods and accessors are not allowed in workflow meta.`);
				continue;
			}
			if (!ts.isPropertyAssignment(prop)) {
				errors.push(`${path}: only property assignments are allowed in workflow meta.`);
				continue;
			}
			if (prop.name.kind === ts.SyntaxKind.ComputedPropertyName) {
				errors.push(`${path}: computed keys are not allowed in workflow meta.`);
				continue;
			}
			const key = propertyNameText(prop.name);
			if (!key) {
				errors.push(`${path}: unsupported property key in workflow meta.`);
				continue;
			}
			out[key] = literalToValue(prop.initializer, `${path}.${key}`, errors);
		}
		return out;
	}
	if (ts.isArrayLiteralExpression(node)) {
		return node.elements.map((el, i) => {
			if (ts.isSpreadElement(el)) {
				errors.push(`${path}[${i}]: spreads are not allowed in workflow meta.`);
				return null;
			}
			return literalToValue(el, `${path}[${i}]`, errors);
		});
	}
	if (ts.isStringLiteral(node) || ts.isNoSubstitutionTemplateLiteral(node)) return node.text;
	if (node.kind === ts.SyntaxKind.TrueKeyword) return true;
	if (node.kind === ts.SyntaxKind.FalseKeyword) return false;
	if (node.kind === ts.SyntaxKind.NullKeyword) return null;
	if (ts.isNumericLiteral(node)) return Number(node.text);
	if (ts.isPrefixUnaryExpression(node) && ts.isNumericLiteral(node.operand)) {
		const n = Number(node.operand.text);
		if (node.operator === ts.SyntaxKind.MinusToken) return -n;
		if (node.operator === ts.SyntaxKind.PlusToken) return n;
	}
	errors.push(`${path}: only pure literals are allowed in workflow meta; found ${ts.SyntaxKind[node.kind]}.`);
	return null;
}

function propertyNameText(name: ts.PropertyName): string | null {
	if (ts.isIdentifier(name) || ts.isStringLiteral(name) || ts.isNumericLiteral(name)) return name.text;
	return null;
}

function validateMetaShape(value: Record<string, unknown>): string[] {
	const errors: string[] = [];
	if (typeof value.name !== "string" || value.name.trim() === "") errors.push("meta.name must be a non-empty string.");
	if (typeof value.description !== "string" || value.description.trim() === "") errors.push("meta.description must be a non-empty string.");
	if (!Array.isArray(value.phases)) {
		errors.push("meta.phases must be an array of { title, detail? } objects.");
	} else {
		value.phases.forEach((phase, i) => {
			if (!isRecord(phase)) {
				errors.push(`meta.phases[${i}] must be an object.`);
				return;
			}
			if (typeof phase.title !== "string" || phase.title.trim() === "") {
				errors.push(`meta.phases[${i}].title must be a non-empty string.`);
			}
			if ("detail" in phase && typeof phase.detail !== "string") {
				errors.push(`meta.phases[${i}].detail must be a string when present.`);
			}
		});
	}
	if ("whenToUse" in value && typeof value.whenToUse !== "string") errors.push("meta.whenToUse must be a string when present.");
	return errors;
}

function isRecord(value: unknown): value is Record<string, unknown> {
	return value !== null && typeof value === "object" && !Array.isArray(value);
}


--- src/index.ts
/**
 * pi-workflow — deterministic JavaScript workflow orchestrator.
 *
 * Clones Claude Code 2.1.146's Workflow tool, adapted to pi's `ctx.forkAgent`
 * primitive.
 *
 * Surface:
 *   - `code` (inline JS), `name` (built-in/user/project workflow), or `scriptPath` (re-run a persisted run).
 *   - VM sandbox with shimmed Date/Math.random/timers.
 *   - Globals: args, log, phase, budget, agent, parallel, pipeline, workflow.
 *   - `agent()` uses ctx.forkAgent.
 *   - Synchronous execution; result returned inline.
 *   - `/workflows` slash command lists everything available.
 *
 * See DESIGN.md for the multi-phase roadmap.
 */

import { AsyncLocalStorage } from "node:async_hooks";
import { execFileSync } from "node:child_process";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import * as crypto from "node:crypto";
import type {
	AgentHandle,
	AgentToolResult,
	ExtensionAPI,
	ExtensionContext,
} from "@valkyriweb/pi-coding-agent";

type AgentToolDetails = Awaited<ReturnType<AgentHandle["wait"]>>;
import { Text } from "@valkyriweb/pi-tui";
import { Type } from "typebox";
import { buildSandboxContext, DeterminismViolation, runWorkflowScript, type SandboxGlobals } from "./sandbox.ts";
import { discoverWorkflows, findWorkflowByName, loadWorkflowSource, validateMetaLiteral } from "./discovery.ts";
import { wireUltracode } from "./ultracode.ts";
import { wireWorkflowKeyword } from "./workflow-keyword.ts";
import { wireWorkflowCommand, formatWorkflowDetail } from "./workflow-command.ts";
import type { WorkflowAgentCallRecord, WorkflowDetails, WorkflowInput } from "./types.ts";

// Bounds synchronous runaway only (vm sync timeout): an infinite JS loop in the
// script. Live-model agent() calls are async and not counted here.
const SYNC_TIMEOUT_MS = 30_000;
// Generous overall wall cap for FOREGROUND runs so a hung turn can't block
// forever. Claude Code imposes no short workflow timeout (token budget + agent
// cap + async govern instead); background runs pass 0 here and skip the wall cap.
const FOREGROUND_WALL_TIMEOUT_MS = 600_000;
const AGENT_LIFETIME_CAP = 1000;
// Default workflow token budget, matching Claude Code's `task_budget`
// (`{ type: "tokens", total: 128000 }`). The `budget` global meters REAL tokens
// (from each subagent run's usage) against this; scripts self-limit via
// `budget.remaining()`. The hard stop remains the agent() lifetime cap above.
const DEFAULT_TASK_BUDGET_TOKENS = 128_000;
const LOG_LINE_CAP = 1000;
const PARALLEL_DEFAULT_CONCURRENCY = Math.max(2, Math.min(16, (os.cpus()?.length ?? 4) - 2));
const RESULT_PREVIEW_CHARS = 1200;

type ResultArtifact = NonNullable<WorkflowDetails["resultArtifact"]>;

// Verbatim from Claude Code 2.1.153 (RunWorkflow). Kept as a module-level
// constant so every workflow subagent fork shares a byte-identical system
// prompt → one warm Anthropic cache entry across every cwd and session.
const WORKFLOW_SUBAGENT_SYSTEM =
	"You are a subagent spawned by a workflow orchestration script. Use the tools available to complete the task.";
// Claude Code 2.1.153 run-id shape: ^wf_[a-z0-9-]{6,}$
const WORKFLOW_RUN_ID_RE = /^wf_[a-z0-9-]{6,}$/;
const makeRunId = () => `wf_${Date.now().toString(36)}${crypto.randomBytes(3).toString("hex")}`;

// ── StructuredOutput tool-call return (Claude Code 2.1.153 1:1) ──────────────
// CC subagents return structured output by CALLING a tool, not by emitting JSON
// text. We mirror that without busting the subagent cache: a SINGLE
// schema-agnostic `StructuredOutput` tool (byte-identical params every call) is
// registered on the forked child when it reports the matching forkMetadata, and
// the per-call schema is validated script-side. Parent and child share this
// process, so the captured value rides back through this module-level map keyed
// by a callId passed via `forkAgent({ metadata })`.
const STRUCTURED_OUTPUT_TOOL = "StructuredOutput";
const STRUCTURED_OUTPUT_META_KEY = "piWorkflowStructuredOutputCallId";
const structuredOutputCaptures = new Map<string, { captured: boolean; value?: unknown }>();

// ── Journal + resume (CC 2.1.153 resumeFromRunId / phase 4) ─────────────────
// Each agent() result is journaled under a DETERMINISTIC call-path key, so a
// resumed run replays completed steps (no re-fork, no tokens) and only the
// unfinished tail re-executes. Determinism is what makes this sound: workflow
// scripts can't read wall-clock/random, so the same script takes the same path
// and issues the same agent() calls in the same logical positions.
//
// The key is a call PATH, not a flat counter: parallel()/pipeline() namespace
// their children by index (`/pN`, `/sN`) and agent() appends a per-scope ordinal
// (`#N`). Because each child's array index is fixed and calls within a scope are
// sequential, the key is identical across runs regardless of which subagent
// finishes first — the one correctness trap with concurrent parallel tasks.
interface CallScope {
	path: string;
	counter: { n: number };
}
const callScopeStore = new AsyncLocalStorage<CallScope>();

function isWorkflowRunId(runId: string): boolean {
	return WORKFLOW_RUN_ID_RE.test(runId);
}

function runDir(cwd: string, runId: string): string {
	if (!isWorkflowRunId(runId)) throw new Error(`Invalid workflow run id: ${runId}`);
	return path.join(cwd, ".pi", "workflows", "runs", runId);
}

function appendJournal(cwd: string, runId: string, key: string, result: unknown): void {
	try {
		fs.appendFileSync(path.join(runDir(cwd, runId), "journal.jsonl"), `${JSON.stringify({ key, result })}\n`, {
			mode: 0o600,
		});
	} catch {
		/* best-effort: journaling never blocks a run */
	}
}

// ── Background / async launch (CC async + taskId) ───────────────────────
// A `background` launch runs the workflow detached (subagents driven by a
// workflow-owned AbortController, NOT the launching turn's signal, so they
// survive past the turn) and returns a taskId immediately. Progress/result are
// persisted to runs/<id>/meta.json and polled via `checkRunId`. The registry
// tracks in-flight runs so they can be aborted on session dispose.
interface BackgroundRun {
	controller: AbortController;
	promise: Promise<unknown>;
	startedAt: number;
}
const backgroundRuns = new Map<string, BackgroundRun>();

function readRunStatus(cwd: string, runId: string): { status: string; text: string } {
	if (!isWorkflowRunId(runId)) return { status: "invalid", text: `Invalid workflow run id '${runId}'. Expected ${WORKFLOW_RUN_ID_RE}.` };
	const live = backgroundRuns.has(runId);
	let meta: { status?: string; details?: WorkflowDetails; result?: unknown; resultArtifact?: ResultArtifact; error?: string } | undefined;
	try {
		meta = JSON.parse(fs.readFileSync(path.join(runDir(cwd, runId), "meta.json"), "utf8"));
	} catch {
		if (!live) return { status: "unknown", text: `No workflow run '${runId}' found.` };
	}
	const status = live && (!meta || meta.status === "running") ? "running" : (meta?.status ?? "running");
	const d = meta?.details;
	const lines = [`Workflow ${runId}: ${status}${d ? ` · ${d.agentCount} agent(s) · ${d.durationMs}ms` : ""}`];
	if (d?.phases?.length) lines.push(`phases: ${d.phases.join(" → ")}`);
	if (meta?.error) lines.push(`error: ${meta.error}`);
	if (status === "completed") {
		const artifact = meta?.details?.resultArtifact ?? meta?.resultArtifact;
		if (artifact) lines.push(formatArtifactNotice(artifact));
		else if (meta?.result !== undefined) {
			const r = meta.result;
			lines.push(`result preview:\n${truncateResultText(typeof r === "string" ? r : JSON.stringify(r, null, 2), 1200)}`);
		}
	}
	return { status, text: lines.join("\n") };
}

function loadJournal(cwd: string, runId: string): Map<string, unknown> {
	const replay = new Map<string, unknown>();
	let raw: string;
	try {
		raw = fs.readFileSync(path.join(runDir(cwd, runId), "journal.jsonl"), "utf8");
	} catch {
		return replay;
	}
	for (const line of raw.split("\n")) {
		if (!line.trim()) continue;
		try {
			const entry = JSON.parse(line) as { key: string; result: unknown };
			replay.set(entry.key, entry.result);
		} catch {
			/* skip a torn trailing line */
		}
	}
	return replay;
}

// ── Worktree isolation (CC isolation:"worktree") ────────────────────────
// A subagent launched with { isolation: "worktree" } runs inside a fresh git
// worktree (its own branch off HEAD), so its writes never touch the parent
// checkout. Forked via the core forkAgent({ cwd }) seam; the worktree is removed
// when the subagent settles (success or failure).
interface WorktreeHandle {
	path: string;
	branch: string;
}

function git(cwd: string, args: string[]): string {
	return execFileSync("git", args, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }).trim();
}

function isGitWorkTree(cwd: string): boolean {
	try {
		return git(cwd, ["rev-parse", "--is-inside-work-tree"]) === "true";
	} catch {
		return false;
	}
}

function createWorktree(repoCwd: string, label: string | undefined): WorktreeHandle {
	const id = `${(label ?? "agent").replace(/[^a-zA-Z0-9_-]/g, "_").slice(0, 24)}-${crypto.randomBytes(4).toString("hex")}`;
	const wtPath = path.join(os.tmpdir(), "pi-workflow-worktrees", id);
	const branch = `pi-wf/${id}`;
	fs.mkdirSync(path.dirname(wtPath), { recursive: true });
	git(repoCwd, ["worktree", "add", "-b", branch, wtPath, "HEAD"]);
	return { path: wtPath, branch };
}

function removeWorktree(repoCwd: string, wt: WorktreeHandle): void {
	try {
		git(repoCwd, ["worktree", "remove", "--force", wt.path]);
	} catch {
		/* best-effort */
	}
	try {
		git(repoCwd, ["branch", "-D", wt.branch]);
	} catch {
		/* best-effort */
	}
}

function structuredOutputInstruction(schema: Record<string, unknown>): string {
	return (
		`\n\nNOTE: You are running inside a workflow script. You MUST return your final answer by calling the \`${STRUCTURED_OUTPUT_TOOL}\` tool; do NOT put your answer in a text response (the script reads ONLY the tool call). If validation fails, read the error and call \`${STRUCTURED_OUTPUT_TOOL}\` again with a corrected shape.` +
		`\nCRITICAL: You MUST call the \`${STRUCTURED_OUTPUT_TOOL}\` tool exactly once to return your final answer as the \`result\` argument, matching this schema:\n${JSON.stringify(schema)}\nAfter calling ${STRUCTURED_OUTPUT_TOOL} successfully, end your turn.`
	);
}

// Surface mirrors Claude Code `RunWorkflow`, with Pi-specific guardrails where
// local model failures showed ambiguity. Keep script API guidance here (the tool
// schema is what teaches the model how workflows work); the keyword reminder
// stays close to Claude Code's minimal routing nudge.
const WORKFLOW_SCRIPT_DESCRIPTION =
	"Self-contained workflow script. Must begin with `export const meta = { name, description, phases }` " +
	"(pure literal, no computed values). Script bodies orchestrate subagents with `agent()`/`parallel()`/`pipeline()`/`phase()`/`log()`; " +
	"they do not expose Bash/Read/Edit or other native tools directly. For checks that need tools, call `agent()` with a concrete task. " +
	"`phase(title)` is only a marker and takes no callback: write `phase(\"audit\"); const findings = await parallel([() => agent(\"…\")]);` " +
	"at top level, never `phase(\"audit\", async () => { … })`.";

const WorkflowParams = Type.Object({
	script: Type.Optional(
		Type.String({
			description: WORKFLOW_SCRIPT_DESCRIPTION,
			maxLength: 50_000,
		}),
	),
	name: Type.Optional(
		Type.String({
			description:
				"Name of a predefined workflow (built-in or from .pi/workflows/). Resolves to a self-contained script.",
		}),
	),
	args: Type.Optional(
		Type.Unknown({
			description:
				"Optional input value exposed to the script as the global `args`. Use for parameterized named workflows (e.g. a research question).",
		}),
	),
	scriptPath: Type.Optional(
		Type.String({
			description:
				"Path to a workflow script file on disk. Every Workflow invocation persists its script under the session directory and returns the path in the tool result. To iterate, edit that file with Write/Edit and re-invoke Workflow with the same `scriptPath` instead of re-sending the full script. Takes precedence over `script` and `name`.",
		}),
	),
	resumeFromRunId: Type.Optional(
		Type.String({
			description:
				"Run ID of a prior Workflow invocation to resume from. Completed agent() steps are replayed from the run's journal (no re-fork); only new/unfinished steps run. Determinism-based.",
		}),
	),
	background: Type.Optional(
		Type.Boolean({
			description:
				"Launch the workflow in the background and return a taskId immediately instead of blocking on completion. Use for long fan-outs. Poll progress/result later with `checkRunId`. Subagents keep running past the launching turn.",
		}),
	),
	checkRunId: Type.Optional(
		Type.String({
			description:
				"Return the current status, progress and (if finished) result of a previously launched workflow run (taskId from a `background` launch, or any prior runId). Does not start a new run.",
		}),
	),
});

// disableWorkflows (CC parity): a setting to turn the Workflow tool off. pi
// extensions can't read user settings directly yet, so this uses the idiomatic
// pi toggle — an env var (set once in ~/.profile). When off, nothing is
// registered: no Workflow tool in the prompt/tool list, no /workflows command.
function workflowsDisabled(): boolean {
	const v = (process.env.PI_DISABLE_WORKFLOWS ?? "").trim().toLowerCase();
	return v === "1" || v === "true" || v === "yes" || v === "on";
}

export default function (pi: ExtensionAPI) {
	if (workflowsDisabled()) return;
	// ultracode session mode depends on the Workflow tool (CC gates it on
	// "workflows enabled"), so it is wired here — only when workflows are on.
	wireUltracode(pi);
	// Per-turn `workflow`/`workflows` keyword nudge toward the Workflow tool
	// (CC 2.1.156). Also gated on workflows being enabled, same reason.
	wireWorkflowKeyword(pi);
	// Abort any in-flight background workflow runs when the session goes away.
	pi.onSessionDispose(() => {
		for (const run of backgroundRuns.values()) run.controller.abort();
		backgroundRuns.clear();
	});
	// When THIS extension instance is running inside a workflow subagent fork
	// (forkMetadata carries our callId), register the schema-agnostic
	// StructuredOutput return tool on the child only. Registered post-fork so it
	// is active for the child's turn; never touches the parent's tool list/cache.
	pi.on("session_start", (event) => {
		const callId = (event as { forkMetadata?: Record<string, unknown> }).forkMetadata?.[STRUCTURED_OUTPUT_META_KEY];
		if (typeof callId !== "string" || !structuredOutputCaptures.has(callId)) return;
		pi.registerTool({
			name: STRUCTURED_OUTPUT_TOOL,
			label: STRUCTURED_OUTPUT_TOOL,
			description: "Return your final structured answer to the workflow script. Call exactly once with the `result` argument, then end your turn.",
			parameters: Type.Object({
				result: Type.Unknown({ description: "Your final answer, matching the schema described in the prompt." }),
			}),
			execute: async (_id, params) => {
				const entry = structuredOutputCaptures.get(callId);
				if (entry) {
					entry.value = (params as { result: unknown }).result;
					entry.captured = true;
				}
				return { content: [{ type: "text", text: "Structured answer recorded. End your turn." }], details: {} };
			},
		});
	});

	pi.registerTool({
		name: "Workflow",
		label: "Workflow",
		description:
			"orchestrate subagents with deterministic JavaScript workflow. Script code uses agent()/parallel()/pipeline()/phase()/log(); put Bash/Read/Edit work inside agent() tasks, not direct script calls.",
		parameters: WorkflowParams,

		async execute(_toolCallId, params, signal, onUpdate, ctx) {
			const input = params as WorkflowInput;

			// Status poll for a prior/background run — no new run.
			if (input.checkRunId) {
				const { text } = readRunStatus(ctx.cwd, input.checkRunId);
				return { content: [{ type: "text", text }], details: {} as unknown as AgentToolDetails };
			}

			const runId = makeRunId();
			const startedAt = Date.now();

			// Resume: re-run the prior run's exact script, replaying journaled agent()
			// results so only the unfinished tail re-forks. Fresh run: empty replay.
			let resolved: { origin: "inline" | "named" | "persisted"; source: string; name?: string; path?: string };
			let replay: Map<string, unknown>;
			if (input.resumeFromRunId) {
				if (!isWorkflowRunId(input.resumeFromRunId)) {
					return errorResult(`Invalid resumeFromRunId '${input.resumeFromRunId}'. Expected ${WORKFLOW_RUN_ID_RE}.`);
				}
				const priorScript = path.join(runDir(ctx.cwd, input.resumeFromRunId), "script.js");
				if (!fs.existsSync(priorScript)) {
					return errorResult(
						`resumeFromRunId: no persisted run '${input.resumeFromRunId}' (expected ${priorScript}).`,
					);
				}
				resolved = { origin: "persisted", source: fs.readFileSync(priorScript, "utf8"), path: priorScript };
				replay = loadJournal(ctx.cwd, input.resumeFromRunId);
			} else {
				const r = resolveSource(input, ctx.cwd);
				if ("error" in r) return errorResult(r.error);
				resolved = r;
				replay = new Map();
			}

			// Inline (dynamic) workflows are allowed once the model calls the
			// Workflow tool. No per-run approval prompt; PI_DISABLE_WORKFLOWS
			// remains the global kill switch.
			const scriptPath = persistScript(ctx.cwd, runId, resolved.source, {
				origin: resolved.origin,
				name: resolved.name,
				path: resolved.path,
			});
			// Seed the new run's journal with replayed steps so it stays self-contained
			// (a resume of a resume reads one journal, not a chain).
			for (const [key, value] of replay) appendJournal(ctx.cwd, runId, key, value);

			// Deterministic call-path scope for journal keys (see helpers above).
			const rootScope: CallScope = { path: "", counter: { n: 0 } };
			const currentScope = (): CallScope => callScopeStore.getStore() ?? rootScope;
			const nextCallKey = (): string => {
				const scope = currentScope();
				return `${scope.path}#${scope.counter.n++}`;
			};

			const logs: string[] = [];
			const phases: string[] = [];
			const agentCalls: WorkflowAgentCallRecord[] = [];
			let agentCount = 0;

			if (resolved.origin !== "inline") {
				// Surface what we're running so the model can reason about it.
				// Inline scripts log themselves implicitly via the source preview.
			}

			const pushLog = (line: string) => {
				if (logs.length < LOG_LINE_CAP) logs.push(line);
				emitUpdate();
			};

			// Set once the run settles (success/error/timeout) or for background runs.
			// A late progress update — e.g. an in-flight parallel() fork settling after
			// the script already errored/timed out — must NOT call onUpdate: that pushes
			// into a turn that's already closed and crashes the process with
			// "Agent listener invoked outside active run".
			let settled = false;
			const emitUpdate = () => {
				if (!onUpdate || settled) return;
				const partial: WorkflowDetails = {
					runId,
					scriptPath,
					source: "inline",
					phases: [...phases],
					agentCount,
					logs: [...logs],
					agentCalls: [...agentCalls],
					startedAt,
					durationMs: Date.now() - startedAt,
				};
				try {
					onUpdate({
						content: [{ type: "text", text: `Workflow ${runId}${resolved.name ? ` (${resolved.name})` : ""}: ${agentCount} agent(s), ${logs.length} log(s)` }],
						details: partial as unknown as AgentToolDetails,
					});
				} catch {
					// Run already settled; the final tool result carries the details.
				}
			};

			const budgetState = { spent: 0, total: DEFAULT_TASK_BUDGET_TOKENS as number | null };
			// One run-scoped controller drives every subagent fork. Sync runs chain the
			// turn signal so a user abort propagates; background runs swap in a detached
			// controller below so subagents survive past the launching turn. Aborted when
			// the run settles so lingering parallel() forks (after an error/timeout) are
			// cancelled instead of settling later and emitting into a closed turn.
			const runController = new AbortController();
			if (signal) {
				if (signal.aborted) runController.abort();
				else signal.addEventListener("abort", () => runController.abort(), { once: true });
			}
			let runSignal: AbortSignal = runController.signal;
			let currentPhase: string | undefined;
			const globals: SandboxGlobals = {
				args: input.args,
				cwd: ctx.cwd,
				log: (msg) => pushLog(msg),
				phase: (title) => {
					currentPhase = title;
					phases.push(title);
					pushLog(`── ${title} ──`);
				},
				budget: {
					get total() {
						return budgetState.total;
					},
					spent: () => budgetState.spent,
					remaining: () => (budgetState.total === null ? Infinity : Math.max(0, budgetState.total - budgetState.spent)),
				},
				agent: async (prompt, opts = {}) => {
					// Key is assigned synchronously at call entry → deterministic
					// order even for concurrent calls (the array is built in order).
					const key = nextCallKey();
					if (replay.has(key)) {
						agentCalls.push({
							seq: agentCalls.length,
							prompt,
							label: opts.label as string | undefined,
							phase: currentPhase,
							model: opts.model as string | undefined,
							durationMs: 0,
							resultPreview: "(replayed from journal)",
							status: "replayed",
						});
						pushLog(`↺ replayed ${key}`);
						emitUpdate();
						return replay.get(key) as string | object;
					}
					if (agentCount >= AGENT_LIFETIME_CAP) {
						// Message mirrors Claude Code 2.1.153.
						throw new Error(
							`Workflow agent() call cap reached (${AGENT_LIFETIME_CAP}). This usually means a loop using budget.remaining() never terminates. Add a hard iteration cap to the loop, or pass a token budget.`,
						);
					}
					agentCount++;
					// Live record so the TUI tree shows the subagent as it runs, then
					// flips it to done/error in place when it settles.
					const livePhase = currentPhase;
					const liveIndex =
						agentCalls.push({
							seq: agentCalls.length,
							prompt,
							label: opts.label as string | undefined,
							phase: livePhase,
