	assert.ok(Array.isArray(dr.meta.phases));
	assert.equal(dr.meta.phases.length, 5);
	assert.equal(dr.meta.phases[0].title, "Scope");
});

test("parseMetaLiteral handles JS object literals with single-quoted strings and trailing commas", () => {
	const meta = parseMetaLiteral(`
		export const meta = {
			name: 'thing',
			description: "does things",
			whenToUse: 'sometimes',
			phases: [
				{ title: 'one', },
			],
		};
		// body...
	`);
	assert.ok(meta);
	assert.equal(meta.name, "thing");
	assert.equal(meta.phases[0].title, "one");
});

test("validateMetaLiteral rejects impure meta with useful errors", () => {
	const cases = [
		[`export const meta = { name: "x", description: "x", ...extra };`, /spreads/],
		[`export const meta = { ["name"]: "x", description: "x" };`, /computed keys/],
		[`export const meta = { name: "x", description() { return "x"; } };`, /methods and accessors/],
		[`export const meta = { name: makeName(), description: "x" };`, /CallExpression/],
		[`export const meta = { name: "x", description: "x" };`, /meta\.phases/],
		[`export const meta = { name: "x", description: "x", phases: [{ detail: "missing" }] };`, /title/],
	];
	for (const [source, pattern] of cases) {
		const result = validateMetaLiteral(source);
		assert.equal(result.meta, null);
		assert.match(result.errors.join("\n"), pattern);
	}
});

test("parseMetaLiteral returns null on garbage", () => {
	assert.equal(parseMetaLiteral("// nothing here"), null);
	assert.equal(parseMetaLiteral("export const meta = WTF;"), null);
});

test("project workflow overrides user overrides builtin", () => {
