		`export const meta = { name: "deep-research", description: "project override", phases: [{ title: "Shadow" }] };\nreturn "shadow";`,
	);

	const all = discoverWorkflows(tmp);
	const dr = all.find((w) => w.name === "deep-research");
	assert.ok(dr);
	assert.equal(dr.source, "project");
	assert.equal(dr.meta.description, "project override");

	// Cleanup
	fs.rmSync(tmp, { recursive: true, force: true });
});

test("deep-research script body compiles in the sandbox", async () => {
	const { runWorkflowScript } = await jiti.import("../src/sandbox.ts");
	const dr = findWorkflowByName("/tmp", "deep-research");
	assert.ok(dr);
	const source = loadWorkflowSource(dr.path);

	// Build a sandbox with agent() that always returns the bail-early branch.
	// We pass empty args → the script should hit `if (!QUESTION) return {error}` early.
	const ctx = buildSandboxContext({
		args: "",
		cwd: "/tmp/workflow-cwd",
		log: () => {},
		phase: () => {},
		budget: { total: null, spent: () => 0, remaining: () => Infinity },
		agent: async () => {
			throw new Error("agent should not be called when args is empty");
		},
		parallel: async (tasks) => Promise.all(tasks.map((t) => t())),
		pipeline: async (itemsOrStages, ...stages) => {
			if (stages.length === 0) {
				const o = [];
				for (const s of itemsOrStages) o.push(await s());
				return o;
			}
			return Promise.all(itemsOrStages.map(async (item, index) => {
				let value = item;
				for (const stage of stages) value = await stage(value, index);
				return value;
			}));
		},
		workflow: async () => {
			throw new Error("not impl");
		},
	});

	const result = await runWorkflowScript(source, ctx, { timeoutMs: 5000, filename: "dr.js" });
	assert.ok(result.error, `expected early-bail error result, got: ${JSON.stringify(result)}`);
	assert.match(result.error, /No research question/);
});

