import assert from "node:assert/strict";
import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";
import { createJiti } from "jiti";

const jiti = createJiti(import.meta.url, { interopDefault: true, fsCache: false });
const mod = await jiti.import("../src/workflow-command.ts");
const {
	parseWorkflowCommand,
	formatWorkflowDetail,
	scaffoldFileName,
	workflowTemplate,
	scaffoldWorkflow,
} = mod;

// --- parse ----------------------------------------------------------------
{
	assert.deepEqual(parseWorkflowCommand(""), { action: "list" });
	assert.deepEqual(parseWorkflowCommand("   "), { action: "list" });
	assert.deepEqual(parseWorkflowCommand("deep-research"), { action: "show", name: "deep-research" });
	assert.deepEqual(parseWorkflowCommand("  deep-research  "), { action: "show", name: "deep-research" });
	assert.deepEqual(parseWorkflowCommand("new"), { action: "new", name: null });
	assert.deepEqual(parseWorkflowCommand("New my flow"), { action: "new", name: "my flow" });
	assert.deepEqual(parseWorkflowCommand("NEW   triage"), { action: "new", name: "triage" });
}

// --- detail formatter -----------------------------------------------------
{
	const wf = {
		name: "triage",
		source: "project",
		path: "/x/.pi/workflows/triage.mjs",
		meta: { name: "triage", description: "d", whenToUse: "when X", phases: [{ title: "A" }, { title: "B" }] },
	};
	const out = formatWorkflowDetail(wf);
	assert.ok(out.includes("triage (project)"), "name + source");
	assert.ok(out.includes("/x/.pi/workflows/triage.mjs"), "path");
	assert.ok(out.includes("Phases: A → B"), "phases joined");
	assert.ok(out.includes("when X"), "whenToUse");

	const bare = formatWorkflowDetail({ name: "n", source: "user", path: "/p", meta: { name: "n", description: "d" } });
	assert.ok(bare.includes("(no phases declared)") && bare.includes("(no usage hint)"), "graceful defaults");
}

// --- filename slug --------------------------------------------------------
{
	assert.equal(scaffoldFileName("My Cool Flow!"), "my-cool-flow.mjs");
	assert.equal(scaffoldFileName("  --weird__name--  "), "weird-name.mjs");
	assert.equal(scaffoldFileName(""), "untitled.mjs");
}

// --- template is valid discoverable meta ----------------------------------
{
	const tpl = workflowTemplate("triage");
	assert.ok(/export const meta = \{/.test(tpl), "has meta export");
	assert.ok(tpl.includes('name: "triage"'), "name baked in");
	// The discovery parser must be able to read the scaffold's meta.
	const disc = await jiti.import("../src/discovery.ts");
	const meta = disc.parseMetaLiteral(tpl);
	assert.ok(meta && meta.name === "triage", "scaffold meta is discoverable");
}

// --- template escapes JS string content ------------------------------------
{
	const tricky = `bad"; throw new Error("boom"); //\nnext */ line`;
	const tpl = workflowTemplate(tricky);
	const disc = await jiti.import("../src/discovery.ts");
	const meta = disc.parseMetaLiteral(tpl);
	assert.ok(meta, "escaped tricky name still parses");
	assert.equal(meta.name, tricky, "tricky name remains data, not code");
	assert.ok(!tpl.includes("//\nnext */"), "comment text is single-line/sanitized");
}

// --- scaffold writes + refuses overwrite ----------------------------------
{
	const cwd = fs.mkdtempSync(path.join(os.tmpdir(), "wf-cmd-"));
	const r1 = scaffoldWorkflow(cwd, "Triage Flow");
	assert.equal(r1.created, true, "first write creates");
	assert.ok(fs.existsSync(r1.path), "file exists");
	assert.ok(r1.path.endsWith("/.pi/workflows/triage-flow.mjs"), "correct location");

	const r2 = scaffoldWorkflow(cwd, "Triage Flow");
	assert.equal(r2.created, false, "second write refuses overwrite");
	assert.equal(r2.path, r1.path, "same path reported");

	fs.rmSync(cwd, { recursive: true, force: true });
}

