  1101	async function runParallel<T>(tasks: Array<() => Promise<T>>, concurrency: number): Promise<T[]> {
  1102		if (tasks.length === 0) return [];
  1103		const limit = Math.max(1, Math.min(concurrency, tasks.length));
  1104		const results: T[] = new Array(tasks.length);
  1105		let nextIndex = 0;
  1106		const workers = new Array(limit).fill(null).map(async () => {
  1107			while (true) {
  1108				const i = nextIndex++;
  1109				if (i >= tasks.length) return;
  1110				results[i] = await tasks[i]();
  1111			}
  1112		});
  1113		await Promise.all(workers);
  1114		return results;
